    TPMS_SIGNATURE_ECDAA ecdaa;         /* all asymmetric signatures */
    TPMS_SIGNATURE_SM2 sm2;             /* all asymmetric signatures */
    TPMS_SIGNATURE_ECSCHNORR ecschnorr; /* all asymmetric signatures */
