// Generate a random TSS2_RC (uint32_t) and decode it to a string.
TSS2_RC rc = (TSS2_RC)(*FUZZ_PARAM(unsigned int));
// Call target function
const char *desc = Tss2_RC_Decode(rc);
// The returned pointer is const and must not be freed or modified; ensure it is non-null.
if (!desc) { FUZZ_BAIL(); }
// Validation: Non-null returned description pointer suggests successful decode path coverage.

// Fuzz layer in range [0,255]
uint8_t layer = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
// Fuzz a name string; may be used by implementation as an identifier/label
std::string name = FUZZ_PARAM_STR();
// We cannot safely synthesize a new function pointer here (no new top-level functions allowed),
// so exercise the unregister path by setting the handler to NULL.
TSS2_RC_HANDLER prev = Tss2_RC_SetHandler(layer, name.c_str(), (TSS2_RC_HANDLER)nullptr);
// If a previous handler existed, restore it immediately to avoid leaving global state altered.
if (prev) {
    (void)Tss2_RC_SetHandler(layer, name.c_str(), prev);
}
// Validation: Exercises install/uninstall code paths without leaking or leaving altered global state.

// Allocate output structure (persistent for fuzzer pool)
TSS2_RC_INFO *info = new TSS2_RC_INFO{};
// Fuzz an input return code to decode
TSS2_RC rc = (TSS2_RC)(*FUZZ_PARAM(unsigned int));
// Invoke the decoder; in TSS2, success is conventionally 0 (TSS2_RC_SUCCESS)
TSS2_RC st = Tss2_RC_DecodeInfo(rc, info);
if (st != 0) {
    // On failure, do not leak persistent state into the pool
    delete info;
    FUZZ_BAIL();
}
// Mark the object as decoded for downstream stubs (e.g., Tss2_RC_DecodeInfoError)
FUZZ_SET_ATTR_INT(info, "decoded", 1);
// Optionally track the source rc for more nuanced testing later
FUZZ_SET_ATTR_INT(info, "rc_low32", (int)rc);
// Output: info is returned to the pool for reuse.
// Validation: Ensures non-null output, checks success, and tags with attributes for later use.

// Require that 'info' was previously populated by Tss2_RC_DecodeInfo
int was_decoded = FUZZ_GET_ATTR_INT(info, "decoded");
if (!was_decoded) { FUZZ_BAIL(); }
// Call the target function to obtain a human-readable description for the decoded info
const char *desc = Tss2_RC_DecodeInfoError(info);
// Returned pointer must be non-null and must not be modified/freed by the caller
if (!desc) { FUZZ_BAIL(); }
// We do not take ownership of 'info'; return it to the pool for further use.
