import random
import string
from typing import List

def _rand_printable(r: random.Random, min_len: int, max_len: int) -> bytes:
    # Generate mostly printable ASCII with occasional special chars
    length = r.randint(min_len, max_len)
    choices = string.printable.encode('ascii')
    b = bytearray()
    for _ in range(length):
        if r.random() < 0.08:
            # occasionally insert NUL or non-printable bytes
            b.append(r.randrange(0, 32))
        else:
            b.append(r.choice(choices))
    return bytes(b)

def _rand_c_identifier(r: random.Random, min_len: int, max_len: int) -> bytes:
    # Create something that often looks like a C identifier or path-like token
    start_chars = string.ascii_letters + "_"
    other_chars = start_chars + string.digits + "_-.:/\\"
    length = r.randint(min_len, max_len)
    s = [r.choice(start_chars)]
    for _ in range(length - 1):
        s.append(r.choice(other_chars))
    return ("".join(s)).encode('utf-8')

def _maybe_embed_nuls(r: random.Random, data: bytes) -> bytes:
    # Occasionally embed NULs within the string to exercise C-string edge cases
    if not data:
        return data
    b = bytearray(data)
    if r.random() < 0.3:
        count = r.randint(1, max(1, len(b)//16))
        for _ in range(count):
            idx = r.randrange(0, len(b))
            b[idx] = 0
    return bytes(b)

def _make_name(r: random.Random) -> bytes:
    # Produce a variety of reasonable names the library might accept
    kind = r.random()
    if kind < 0.3:
        name = _rand_c_identifier(r, 1, 32)
    elif kind < 0.6:
        # path-like
        parts = [ _rand_c_identifier(r, 1, 8).decode('utf-8') for _ in range(r.randint(1,4)) ]
        name = ("/".join(parts)).encode('utf-8')
    elif kind < 0.85:
        # readable words joined
        words = ["tpm", "tss2", "layer", "vendor", "mssim", "device", "socket", "custom", "rc", "decode"]
        name = ("-".join(r.choice(words) for _ in range(r.randint(1,3)))).encode('utf-8')
    else:
        name = _rand_printable(r, 0, 64)
    return _maybe_embed_nuls(r, name)

def generate(seed: int) -> bytes:
    """
    Generate a bytes buffer intended for FUZZ_PARAM_STR used by Tss2_RC_SetHandler stub.
    The stub also reads a random unsigned int for layer; the fuzzer will supply that.
    Here we craft interesting name strings, including identifiers, paths, printable and
    embedded NUL cases, within 4096 byte limit.
    We return a single string instance; harness may call FUZZ_PARAM_STR once.
    """
    r = random.Random(seed)

    # Bias towards valid-looking names but include tricky cases
    name = _make_name(r)

    # Ensure a reasonable length distribution and occasionally very short/empty strings
    if r.random() < 0.15:
        name = b""  # empty name
    elif r.random() < 0.2:
        name = b"default"

    # Cap total size
    return name[:4096]
